import React from 'react';
import { Link, Navigate, useParams } from 'react-router-dom';

import Seo from '../components/Seo';
import Icon from '../components/Icon';
import MediaImage from '../components/MediaImage';
import { projects } from '../data/site';

export default function ProjectDetail() {
  const { slug } = useParams();
  const project = projects.find((item) => item.slug === slug);

  if (!project) return <Navigate to="/projets" replace />;

  return (
    <>
      <Seo
        title={project.name}
        path={`/projets/${project.slug}`}
        description={project.intro}
        type="article"
      />

      <section className="project-detail-hero">
        <div className="project-detail-copy">
          <p className="eyebrow"><span />{project.kind} · {project.year}</p>
          <h1>{project.name}</h1>
          <p>{project.headline}</p>
          <div className="hero-actions">
            <a className="primary-action" href={project.url} target="_blank" rel="noopener noreferrer">
              Voir le projet <Icon name="external" />
            </a>
            <Link className="glass-action" to="/contact">J’ai un projet</Link>
          </div>
        </div>

        <div className={`project-detail-visual project-media--${project.slug}`}>
          <MediaImage src={project.image} alt={project.name} className="media-photo" />
          <div className="media-overlay" />
          <div className="detail-glass">
            <span>{project.roles[0]}</span>
            <span>{project.stack[0]}</span>
          </div>
        </div>
      </section>

      <section className="project-detail-body">
        <aside className="glass-card">
          <div>
            <p>Rôle</p>
            {project.roles.map((role) => <span key={role}>{role}</span>)}
          </div>
          <div>
            <p>Technologies</p>
            {project.stack.map((tool) => <span key={tool}>{tool}</span>)}
          </div>
        </aside>

        <article>
          <div><small>Point de départ</small><h2>{project.challenge}</h2></div>
          <div><small>Choix</small><p>{project.approach}</p></div>
          <div><small>Ce que je travaille ici</small><p>{project.detail}</p></div>
        </article>
      </section>

      <section className="case-next">
        <Link to="/projets">← Tous les projets</Link>
        <Link to="/contact">J’ai un projet <Icon name="arrow" size={15} /></Link>
      </section>
    </>
  );
}
